@extends('layouts.store') @section('content')<main class="container py-5"><div class="row justify-content-center"><div class="col-lg-8"><div class="card p-4 p-lg-5"><span class="text-danger fw-bold">CALCULATOR</span><h1 class="mt-2">{{ $product->name }}</h1><p class="text-secondary">{{ $product->description }}</p><div class="row g-3 align-items-end"><div class="col-md-6"><label class="form-label">مقدار مورد نیاز</label><input id="quantity" type="number" min=".01" step=".01" value="1" class="form-control form-control-lg"></div><div class="col-md-6"><button id="calculate" class="btn btn-dark btn-lg w-100">محاسبه قیمت</button></div></div><div id="result" class="mt-4 p-4 rounded-4 bg-light d-none"><div>مقدار: <strong id="q"></strong></div><div>مقدار قابل محاسبه: <strong id="bq"></strong></div><div>پرت: <strong id="w"></strong>%</div><div class="fs-3 mt-2">قیمت نهایی: <strong id="total"></strong></div></div></div></div></div></main><script>document.getElementById('calculate').addEventListener('click',async()=>{const quantity=document.getElementById('quantity').value;const r=await fetch('{{ route('calculator.calculate',$product->slug) }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({quantity})});const d=await r.json();document.getElementById('result').classList.remove('d-none');document.getElementById('q').textContent=d.quantity;document.getElementById('bq').textContent=d.billable_quantity+' {{ $product->pricingRule?->unit ?? '' }}';document.getElementById('w').textContent=d.waste_percent;document.getElementById('total').textContent=new Intl.NumberFormat('fa-IR').format(d.total)+' تومان';});</script>@endsection